package com.streak.app
import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.os.*;import android.view.*;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import androidx.core.app.ActivityCompat;import java.time.*;import java.time.temporal.ChronoUnit;import java.util.Calendar
class MainActivity:AppCompatActivity(){lateinit var p:android.content.SharedPreferences;lateinit var days:TextView;lateinit var check:Button;lateinit var best:TextView;lateinit var total:TextView
override fun onCreate(b:Bundle?){super.onCreate(b);p=getSharedPreferences("streak",MODE_PRIVATE);if(!p.contains("start"))p.edit().putString("start",LocalDate.now().toString()).apply();val r=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(48,70,48,40);gravity=Gravity.CENTER_HORIZONTAL};fun t(s:String,z:Float)=TextView(this).apply{text=s;textSize=z;gravity=Gravity.CENTER};r.addView(t("STREAK",18f));r.addView(t("One day at a time.",15f));days=t("",64f);r.addView(days);r.addView(t("DAYS FREE",16f));check=Button(this).apply{text="✓  I stayed free today";setOnClickListener{checkIn()}};r.addView(check);best=t("",18f);total=t("",18f);r.addView(best);r.addView(total);r.addView(t("\nMilestones  •  1  •  3  •  7  •  14  •  30  •  60  •  90  •  365",16f));r.addView(Button(this).apply{text="🔔 Daily reminder: 8:30 AM";setOnClickListener{schedule(this@MainActivity);Toast.makeText(context,"Reminder set for 8:30 AM",Toast.LENGTH_SHORT).show()}});r.addView(Button(this).apply{text="Reset streak";setOnClickListener{AlertDialog.Builder(this@MainActivity).setTitle("Start a new streak?").setMessage("Best streak and check-ins are kept.").setNegativeButton("Cancel",null).setPositiveButton("Reset"){_,_->reset()}.show()}});setContentView(r);if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)ActivityCompat.requestPermissions(this,arrayOf(Manifest.permission.POST_NOTIFICATIONS),7);schedule(this);refresh()}
fun cur()=ChronoUnit.DAYS.between(LocalDate.parse(p.getString("start",LocalDate.now().toString())),LocalDate.now()).toInt().coerceAtLeast(0)
fun refresh(){val d=cur();days.text="$d";best.text="🏆 Best streak   "+kotlin.math.max(p.getInt("best",0),d)+" days";total.text="✓ Total check-ins   "+p.getInt("total",0);val ok=p.getString("last","")!=LocalDate.now().toString();check.isEnabled=ok;check.text=if(ok)"✓  I stayed free today" else "✓  Checked in today"}
fun checkIn(){p.edit().putString("last",LocalDate.now().toString()).putInt("total",p.getInt("total",0)+1).putInt("best",kotlin.math.max(p.getInt("best",0),cur())).apply();refresh()}
fun reset(){p.edit().putInt("best",kotlin.math.max(p.getInt("best",0),cur())).putString("start",LocalDate.now().toString()).remove("last").apply();refresh()}
companion object{fun schedule(c:Context){val a=c.getSystemService(ALARM_SERVICE) as AlarmManager;val i=Intent(c,ReminderReceiver::class.java);val pi=PendingIntent.getBroadcast(c,830,i,PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE);val x=Calendar.getInstance().apply{set(Calendar.HOUR_OF_DAY,8);set(Calendar.MINUTE,30);set(Calendar.SECOND,0);if(timeInMillis<=System.currentTimeMillis())add(Calendar.DAY_OF_YEAR,1)};a.setInexactRepeating(AlarmManager.RTC_WAKEUP,x.timeInMillis,AlarmManager.INTERVAL_DAY,pi)}}}